$(".save-mapping-button").click(function(){performActionOnWebservice(this,"updateCampaign")});$(".delete-mapping-button").click(function(){performActionOnWebservice(this,"deleteMapping")});function performActionOnWebservice(self,action){mapping_id=$(self).data("mapping_id");campaign=$("#pushtech_campaign_"+mapping_id).val();offer=$("#hotelinking_offer_"+mapping_id).val();id_hotel=$(".add-new-mapping").data("id_hotel");if(action=="updateCampaign")data={campaign:campaign,offer:offer,id_hotel:id_hotel,action:action};if(action=="deleteMapping")data={id:mapping_id,id_hotel:id_hotel};$.ajax({url:"lib/webservices/pushtech_api_webservice.php",data:data,type:"POST",async:false,success:function(output){var data=JSON.parse(output);showError(data.code)}})}